// Which component, for which job.
//
// Reads the `when.ts` beside every component (and `packages/ui/src/*.when.ts` for the CSS-only
// parts and the screen map), checks them, and writes:
//
//   skills/gener8v-design-system/references/choosing/<family>.md   one per family
//   skills/gener8v-design-system/SKILL.md                          the router, between markers
//
//   node scripts/choosing.mjs           check: fail on a gap, a dangling reference or a stale file
//   node scripts/choosing.mjs --write   check, then write the generated files
//
// The gate fails when an exported React component, or a class family in the component index, has
// no entry; when a `not` or a `neighbours` names a component that does not exist; and when a
// generated file differs from what this would write. The text is what Claude acts on when it picks
// a component, so a reference to nothing is a wrong answer, not a typo.
import { readFileSync, readdirSync, existsSync, writeFileSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const UI = join(ROOT, 'packages/ui/src');
const SKILL_DIR = 'skills/gener8v-design-system';
const CHOOSING_DIR = `${SKILL_DIR}/references/choosing`;
export const MARK_START = '<!-- choosing:start — GENERATED by scripts/choosing.mjs from the when.ts files; do not edit between these markers -->';
export const MARK_END = '<!-- choosing:end -->';

/* ------------------------------------------------------------------ load */

/** Every metadata module: `src/<Dir>/when.ts` and `src/*.when.ts`. */
export function whenFiles(ui = UI) {
  const out = [];
  for (const d of readdirSync(ui, { withFileTypes: true })) {
    if (d.isDirectory() && existsSync(join(ui, d.name, 'when.ts'))) out.push(join(ui, d.name, 'when.ts'));
    else if (d.isFile() && d.name.endsWith('.when.ts')) out.push(join(ui, d.name));
  }
  return out.sort();
}

/** Component directories (those with an index.ts) that have no `when.ts` beside them. */
export function dirsWithoutWhen(ui = UI) {
  return readdirSync(ui, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(ui, d.name, 'index.ts')) && !existsSync(join(ui, d.name, 'when.ts')))
    .map((d) => d.name).sort();
}

export async function load(root = ROOT) {
  const ui = join(root, 'packages/ui/src');
  const { FAMILIES } = await import(/* @vite-ignore */ pathToFileURL(join(ui, 'choosing.ts')).href);
  const entries = [];
  const screens = [];
  for (const f of whenFiles(ui)) {
    const mod = await import(/* @vite-ignore */ pathToFileURL(f).href);
    for (const e of mod.when ?? []) entries.push({ ...e, source: f.slice(root.length + 1) });
    screens.push(...(mod.screens ?? []));
  }
  return { FAMILIES, entries, screens };
}

/** Value exports of the package entry, split into components (PascalCase) and the rest. */
export function packageExports(src) {
  const names = [];
  // `export {` only — `export type {` has a word between the two and does not match.
  for (const m of src.matchAll(/export\s*\{([^}]*)\}\s*from/g)) {
    for (const n of m[1].split(',').map((s) => s.trim()).filter(Boolean)) names.push(n.split(/\s+as\s+/).pop());
  }
  return {
    components: names.filter((n) => /^[A-Z][a-z]/.test(n)),
    other: names.filter((n) => !/^[A-Z][a-z]/.test(n)),
  };
}

/** Class names the stylesheet defines. */
export function stylesheetClasses(css) {
  const out = new Set();
  for (const m of css.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/\.([a-z][a-z0-9-]*)/g)) out.add(`.${m[1]}`);
  return out;
}

/** The component index's rows, as the classes each names — the same rows components.md is cut from. */
export function indexRows(readme) {
  return [...readme.matchAll(/^\| (`[^|]+`) \| ([^|]+) \| ([^|]+) \|$/gm)]
    .filter((m) => !m[1].includes('Class'))
    .map((m) => [...m[1].matchAll(/`(\.[a-z][a-z0-9-]*)/g)].map((c) => c[1]));
}

/** The entry that owns a class: the longest root that is the class or a `-`prefix of it. */
export function ownerOf(cls, entries) {
  let best = null;
  let len = 0;
  for (const e of entries) for (const root of e.css) {
    if ((cls === root || cls.startsWith(`${root}-`)) && root.length > len) { best = e; len = root.length; }
  }
  return best;
}

/* -------------------------------------------------------------- validate */

/**
 * Every problem with the metadata, as sentences. Pure: everything it needs is passed in, so the
 * test can hand it a broken registry and watch it fail.
 */
export function validate({ families, entries, screens, exports, classes, rows, exists, missingWhen = [] }) {
  const problems = [];
  const byName = new Map();
  const say = (e, msg) => problems.push(`${e.source ?? e.name}: ${e.name} — ${msg}`);

  for (const d of missingWhen) problems.push(`packages/ui/src/${d}/ has no when.ts — say what it is for and when not to use it`);

  for (const e of entries) {
    if (byName.has(e.name)) say(e, `the name is used twice (also in ${byName.get(e.name).source})`);
    byName.set(e.name, e);
  }

  const claimedBy = new Map();
  const rootOwner = new Map();
  for (const e of entries) {
    if (!families.includes(e.family)) say(e, `family "${e.family}" is not one of ${families.join(', ')}`);
    if (!e.job || !e.job.trim()) say(e, 'has no job');
    if (!Array.isArray(e.use) || e.use.length < 1 || e.use.length > 3) say(e, `"use" needs one to three situations, has ${e.use?.length ?? 0}`);
    if (!Array.isArray(e.not) || e.not.length < 1) say(e, '"not" is empty — say when it is the wrong choice and what to use instead');
    for (const n of e.not ?? []) {
      if (!n.when || !n.because) say(e, `a "not" pointing at ${n.use} is missing its when or its because`);
      if (n.use === e.name) say(e, 'a "not" points at itself');
      else if (!byName.has(n.use)) say(e, `"not" names ${n.use}, which is not a component here`);
    }
    if (!Array.isArray(e.neighbours) || e.neighbours.length < 1) say(e, 'has no neighbours');
    for (const n of e.neighbours ?? []) {
      if (n === e.name) say(e, 'lists itself as a neighbour');
      else if (!byName.has(n)) say(e, `"neighbours" names ${n}, which is not a component here`);
    }
    for (const r of e.react) {
      if (!exports.components.includes(r)) say(e, `React export ${r} is not exported from @gener8v/ui`);
      if (claimedBy.has(r)) say(e, `React export ${r} is also claimed by ${claimedBy.get(r)}`);
      claimedBy.set(r, e.name);
    }
    for (const h of e.hooks ?? []) if (!exports.other.includes(h)) say(e, `hook ${h} is not exported from @gener8v/ui`);
    if (!e.css.length && !e.react.length) say(e, 'has neither a React export nor a class');
    for (const c of e.css) {
      if (!c.startsWith('.')) say(e, `class root "${c}" needs its dot`);
      else if (!classes.has(c)) say(e, `class ${c} is not in styles.css`);
      if (rootOwner.has(c)) say(e, `class root ${c} is also claimed by ${rootOwner.get(c)}`);
      rootOwner.set(c, e.name);
    }
    if (e.page !== null && !exists(`design/${e.page}`)) say(e, `page design/${e.page} does not exist`);
  }

  for (const c of exports.components) {
    if (!claimedBy.has(c)) problems.push(`@gener8v/ui exports ${c}, and no when.ts claims it — add it to its family's entry`);
  }
  for (const row of rows) {
    if (!row.length) continue;
    if (!ownerOf(row[0], entries)) problems.push(`components.md lists ${row[0]}, and no when.ts claims it — add its class root to an entry's css`);
  }
  for (const s of screens) {
    if (!exists(`design/${s.template}`)) problems.push(`screen "${s.screen}": template design/${s.template} does not exist`);
    for (const i of s.implies) if (!entries.some((x) => x.name === i)) problems.push(`screen "${s.screen}" implies ${i}, which is not a component here`);
  }
  return problems;
}

/* ---------------------------------------------------------------- render */

const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const code = (s) => `\`${s}\``;
const cap = (s) => (s && /[a-z]/.test(s[0]) ? s[0].toUpperCase() + s.slice(1) : s);

function where(name, entries, family) {
  const e = entries.find((x) => x.name === name);
  return e && e.family !== family ? `${code(name)} (${e.family}.md)` : code(name);
}

export function renderFamily(family, FAMILIES, entries, screens) {
  const f = FAMILIES[family];
  const mine = entries.filter((e) => e.family === family);
  const lines = [
    `# Choosing: ${f.title.toLowerCase()}`,
    '',
    'GENERATED by `scripts/choosing.mjs` from the `when.ts` beside each component. Do not edit;',
    'change the `when.ts` and run `pnpm build:choosing`.',
    '',
    `For ${f.question}. Find the job, take the component, and read the "not when" before you commit:`,
    'it names the thing people reach for by mistake and what to use instead.',
    '',
  ];

  if (family === 'screens' && screens.length) {
    lines.push('## Screen types', '', 'Start a screen from a template, not from a blank file.', '',
      '| Screen | Start from | Uses | When |', '| --- | --- | --- | --- |');
    for (const s of screens) {
      lines.push(`| ${cell(s.screen)} | ${code(`design/${s.template}`)} | ${s.implies.map((i) => where(i, entries, family)).join(', ')} | ${cell(s.note)} |`);
    }
    lines.push('');
  }

  lines.push('## At a glance', '', '| Job | Use | Not when | Instead | Because |', '| --- | --- | --- | --- | --- |');
  for (const e of mine) {
    e.not.forEach((n, i) => {
      lines.push(`| ${i ? '' : cell(e.job)} | ${i ? '' : `**${code(e.name)}**`} | ${cell(n.when)} | ${where(n.use, entries, family)} | ${cell(n.because)} |`);
    });
  }
  lines.push('');

  for (const e of mine) {
    lines.push(`## ${e.name}`, '', `${cap(e.job)}.`, '', '**Use when**', '');
    for (const u of e.use) lines.push(`- ${u}`);
    lines.push('', '**Not when**', '');
    for (const n of e.not) lines.push(`- ${cap(n.when)} → ${where(n.use, entries, family)}. ${cap(n.because)}`);
    lines.push('', `**Confused with** ${e.neighbours.map((n) => where(n, entries, family)).join(', ')}`, '');
    const parts = [];
    if (e.react.length) parts.push(`React ${e.react.map(code).join(', ')}`);
    if (e.hooks?.length) parts.push(`hooks ${e.hooks.map(code).join(', ')}`);
    if (e.css.length) parts.push(`classes ${e.css.map(code).join(', ')}`);
    parts.push(e.page ? `shown in ${code(`design/${e.page}`)}` : 'no demo page');
    lines.push(parts.join(' · '), '');
  }
  return lines.join('\n');
}

export function renderRouter(FAMILIES, entries, screens) {
  const fams = Object.keys(FAMILIES);
  const lines = [
    MARK_START,
    '## What are you building?',
    '',
    'Pick the row, open the file. Each one opens with a table — job, component, when not, what',
    'instead — then a section per component. Read the "not when" before you choose.',
    '',
    '| If you are building… | Read |',
    '| --- | --- |',
    ...fams.map((f) => `| ${FAMILIES[f].question} | \`references/choosing/${f}.md\` (${entries.filter((e) => e.family === f).length}) |`),
    '',
    '| Screen | Start from |',
    '| --- | --- |',
    ...screens.map((s) => `| ${s.screen} | \`design/${s.template}\` |`),
    MARK_END,
  ];
  return lines.join('\n');
}

/** Every generated file, path → content. SKILL.md is the whole file with the block replaced. */
export function renderAll({ FAMILIES, entries, screens }, skillSource) {
  const out = {};
  for (const f of Object.keys(FAMILIES)) out[`${CHOOSING_DIR}/${f}.md`] = renderFamily(f, FAMILIES, entries, screens);
  const start = skillSource.indexOf(MARK_START.slice(0, 20));
  const end = skillSource.indexOf(MARK_END);
  if (start < 0 || end < 0) throw new Error(`${SKILL_DIR}/SKILL.md has no choosing markers`);
  out[`${SKILL_DIR}/SKILL.md`] = skillSource.slice(0, start) + renderRouter(FAMILIES, entries, screens) + skillSource.slice(end + MARK_END.length);
  return out;
}

/** Generated paths whose content on disk differs from what would be written, plus strays. */
export function stale(rendered, read, listed = []) {
  const out = [];
  for (const [p, body] of Object.entries(rendered)) if (read(p) !== body) out.push(p);
  for (const p of listed) if (!(p in rendered)) out.push(`${p} (not generated by anything — remove it)`);
  return out;
}

/* ------------------------------------------------------------------ main */

async function main() {
  const write = process.argv.includes('--write');
  const reg = await load();
  const rd = (p) => (existsSync(join(ROOT, p)) ? readFileSync(join(ROOT, p), 'utf8') : null);
  const problems = validate({
    families: Object.keys(reg.FAMILIES),
    entries: reg.entries,
    screens: reg.screens,
    exports: packageExports(rd('packages/ui/src/index.ts')),
    classes: stylesheetClasses(rd('design/styles.css')),
    rows: indexRows(rd('design/readme.md')),
    exists: (p) => existsSync(join(ROOT, p)),
    missingWhen: dirsWithoutWhen(),
  });
  if (problems.length) {
    console.error(`✗ choosing — ${problems.length} problem(s)\n${problems.map((p) => `  · ${p}`).join('\n')}`);
    process.exit(1);
  }
  const rendered = renderAll(reg, rd(`${SKILL_DIR}/SKILL.md`));
  if (write) {
    mkdirSync(join(ROOT, CHOOSING_DIR), { recursive: true });
    for (const [p, body] of Object.entries(rendered)) if (rd(p) !== body) { writeFileSync(join(ROOT, p), body); console.log('  ✓', p); }
  }
  const dir = join(ROOT, CHOOSING_DIR);
  const listed = existsSync(dir) ? readdirSync(dir).map((f) => `${CHOOSING_DIR}/${f}`) : [];
  const old = stale(rendered, rd, listed);
  if (old.length) {
    console.error(`✗ choosing — generated files are stale; run \`pnpm build:choosing\`\n${old.map((p) => `  · ${p}`).join('\n')}`);
    process.exit(1);
  }
  const counts = Object.keys(reg.FAMILIES).map((f) => `${f} ${reg.entries.filter((e) => e.family === f).length}`).join(', ');
  console.log(`✓ choosing — ${reg.entries.length} components, ${reg.screens.length} screens (${counts})`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await main();
